    if (!isJS) {
        return GoSlice.of(GoElem.STRING, getJSDocParamAnnotation(emitContext, path, initializer, dotDotDotToken, isJS, false, isSnippet, typeChecker, options, preferences.goCopy(), tabstopCounter))
    }
    return jsDocParamPatternWorker(emitContext, path, pattern, initializer, dotDotDotToken, isJS, isSnippet, typeChecker, options, preferences.goCopy(), tabstopCounter)
}

